create schema if not exists private;
create table if not exists public.toolbox_issues_memberships (workspace_id uuid not null,user_id uuid not null,role text not null check (role in ('team_leader','secretary','standard')),enabled boolean not null default true,assigned_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),primary key (workspace_id,user_id));
create table if not exists public.toolbox_issues (id bigint generated by default as identity primary key,workspace_id uuid not null,name text not null check (char_length(name) between 1 and 500),status text not null default 'Working on it' check (char_length(status) between 1 and 80),person jsonb not null default '[]'::jsonb,target_date date,time_tracking jsonb not null default '{"hours":0,"minutes":0}'::jsonb,payload jsonb not null default '{}'::jsonb,creator_user_id uuid not null,version bigint not null default 1,archived_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists toolbox_issues_workspace_active_idx on public.toolbox_issues(workspace_id,archived_at,updated_at desc);
create table if not exists public.toolbox_issue_subitems (id bigint generated by default as identity primary key,workspace_id uuid not null,issue_id bigint not null references public.toolbox_issues(id) on delete cascade,name text not null check (char_length(name) between 1 and 500),status text not null default 'Working on it' check (char_length(status) between 1 and 80),person jsonb not null default '[]'::jsonb,payload jsonb not null default '{}'::jsonb,version bigint not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists toolbox_issue_subitems_issue_idx on public.toolbox_issue_subitems(workspace_id,issue_id);
create table if not exists public.toolbox_issue_updates (id bigint generated by default as identity primary key,workspace_id uuid not null,issue_id bigint not null references public.toolbox_issues(id) on delete cascade,creator_user_id uuid not null,text_body text not null check (char_length(text_body) between 1 and 20000),created_at timestamptz not null default now());
create index if not exists toolbox_issue_updates_issue_idx on public.toolbox_issue_updates(workspace_id,issue_id,created_at desc);
create table if not exists public.toolbox_issue_attachments (id bigint generated by default as identity primary key,workspace_id uuid not null,issue_id bigint not null references public.toolbox_issues(id) on delete cascade,update_id bigint references public.toolbox_issue_updates(id) on delete cascade,storage_path text not null unique,name text not null check (char_length(name) between 1 and 300),mime_type text not null check (char_length(mime_type) between 1 and 200),size_bytes bigint not null check (size_bytes between 1 and 52428800),creator_user_id uuid not null,created_at timestamptz not null default now());
create index if not exists toolbox_issue_attachments_issue_idx on public.toolbox_issue_attachments(workspace_id,issue_id);
create table if not exists public.toolbox_issues_state (workspace_id uuid not null,key text not null check (char_length(key) between 1 and 160),value text,version bigint not null default 0,updated_by uuid not null,updated_at timestamptz not null default now(),primary key (workspace_id,key));
create table if not exists public.toolbox_issues_activity (id bigint generated by default as identity primary key,workspace_id uuid not null,entity_type text not null,entity_id text,actor_user_id uuid,event_type text not null,detail jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists toolbox_issues_activity_workspace_idx on public.toolbox_issues_activity(workspace_id,created_at desc);
alter table public.toolbox_issues_memberships enable row level security;alter table public.toolbox_issues enable row level security;alter table public.toolbox_issue_subitems enable row level security;alter table public.toolbox_issue_updates enable row level security;alter table public.toolbox_issue_attachments enable row level security;alter table public.toolbox_issues_state enable row level security;alter table public.toolbox_issues_activity enable row level security;
revoke all on public.toolbox_issues_memberships,public.toolbox_issues,public.toolbox_issue_subitems,public.toolbox_issue_updates,public.toolbox_issue_attachments,public.toolbox_issues_state,public.toolbox_issues_activity from anon,authenticated;;
